// probe: control, compile-only
// Native build fails identically on the production and candidate
// artifacts: the backend lowers `del p` inside a match case to a Zig
// capture that shadows the outer constant. Pre-existing backend
// limitation, unrelated to this candidate.
io :: import "std/io"

Inner :: struct {
    value: i32
}

main :: fn() {
    x := 5
    k := 2
    p := new Inner
    if p != nil {
        match k {
            case 1: {
                del p
                fall
            }
            case 2: {
                io.println("{}", 10 / x)
            }
        }
    }
}

// probe: compatibility
// Works on the production compiler and prints 2 natively.
// The candidate rejects it: a call through a local alias is an unknown
// callee and invalidates every mutable global.
io :: import "std/io"

g: i32 = 5

noop :: fn() {
}

main :: fn() {
    g = 5
    h := noop
    h()
    y := 10 / g
    io.println("{}", y)
}

